import{_ as n,C as s,o,c as l,j as a,a as t,b as d,w as r,E as h,a8 as m,a9 as c}from"./chunks/framework.BOiBTRPC.js";const v=JSON.parse('{"title":"Data Platforms","description":"Track 1 — storage architectures, file & table formats, dimensional modeling, and normalization trade-offs.","frontmatter":{"title":"Data Platforms","description":"Track 1 — storage architectures, file & table formats, dimensional modeling, and normalization trade-offs."},"headers":[],"relativePath":"fundamentals/index.md","filePath":"fundamentals/index.md"}'),u={name:"fundamentals/index.md"};function f(p,e,g,w,y,b){const i=s("Mermaid");return o(),l("div",null,[e[1]||(e[1]=a("h1",{id:"data-platforms",tabindex:"-1"},[t("Data Platforms "),a("a",{class:"header-anchor",href:"#data-platforms","aria-label":'Permalink to "Data Platforms"'},"​")],-1)),e[2]||(e[2]=a("blockquote",null,[a("p",null,[a("strong",null,"Why it matters"),t(" — Every downstream decision inherits your platform choices. The storage architecture, file format, and data model you pick decide query cost, correctness, and how much pain every team that touches the data will feel for years.")])],-1)),e[3]||(e[3]=a("p",null,"The storage layer is where every data platform decision compounds. Pick the wrong architecture and you fight it for years; pick the wrong format and every query pays a tax; pick the wrong model and every downstream team re-derives the truth differently.",-1)),e[4]||(e[4]=a("p",null,"This track covers the four platform decisions you make exactly once — and then live with:",-1)),(o(),d(m,null,{default:r(()=>[h(i,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22Storage%20Architectures%22%5D%20--%3E%20B%5B%22File%20and%20Table%20Formats%22%5D%3B%0A%20%20A%20--%3E%20C%5B%22Data%20Modeling%22%5D%3B%0A%20%20C%20--%3E%20D%5B%22Normalization%20vs%20Denormalization%22%5D%3B%0A%20%20B%20-.%20%22Iceberg%20%2F%20Delta%20%2F%20Hudi%22%20.-%3E%20A%3B%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=c('<h2 id="who-this-is-for" tabindex="-1">Who this is for <a class="header-anchor" href="#who-this-is-for" aria-label="Permalink to &quot;Who this is for&quot;">​</a></h2><p>Data engineers, analytics engineers, and architects who need to <em>choose</em> — not just use — the storage and modeling layer. Assumes working SQL and some exposure to a warehouse or lake. This is the vocabulary senior interviews and architecture reviews are conducted in.</p><h2 id="chapters" tabindex="-1">Chapters <a class="header-anchor" href="#chapters" aria-label="Permalink to &quot;Chapters&quot;">​</a></h2><h3 id="storage-architectures" tabindex="-1"><a href="/Data-Knowledge/fundamentals/storage-architectures.html">Storage Architectures</a> <a class="header-anchor" href="#storage-architectures" aria-label="Permalink to &quot;[Storage Architectures](/fundamentals/storage-architectures)&quot;">​</a></h3><p>Warehouse vs lake vs lakehouse vs data mesh — how the industry got from Oracle EDWs to Iceberg-on-S3, what each architecture actually buys you (cost, governance, flexibility, freshness), and where each one fails in production: swamp lakes, lock-in, and organizational meshes that collapse.</p><h3 id="file-table-formats" tabindex="-1"><a href="/Data-Knowledge/fundamentals/file-formats.html">File &amp; Table Formats</a> <a class="header-anchor" href="#file-table-formats" aria-label="Permalink to &quot;[File &amp; Table Formats](/fundamentals/file-formats)&quot;">​</a></h3><p>Row vs columnar layout; Parquet internals (row groups, column chunks, statistics, encodings, predicate pushdown); Avro and Protobuf for row-oriented work; and the ACID table formats — Delta, Iceberg, Hudi — that turned raw files into tables. Plus the small-files problem and codec choice.</p><h3 id="data-modeling" tabindex="-1"><a href="/Data-Knowledge/fundamentals/data-modeling.html">Data Modeling</a> <a class="header-anchor" href="#data-modeling" aria-label="Permalink to &quot;[Data Modeling](/fundamentals/data-modeling)&quot;">​</a></h3><p>Kimball dimensional modeling (grain, facts, conformed dimensions, SCD types), Inmon CIF, Data Vault 2.0, and One Big Table. When each earns its complexity, and how BI and ML consumers pull the model in opposite directions.</p><h3 id="normalization-denormalization" tabindex="-1"><a href="/Data-Knowledge/fundamentals/normalization.html">Normalization &amp; Denormalization</a> <a class="header-anchor" href="#normalization-denormalization" aria-label="Permalink to &quot;[Normalization &amp; Denormalization](/fundamentals/normalization)&quot;">​</a></h3><p>1NF → BCNF with tiny concrete examples, the anomalies normalization prevents, and why the star schema is <em>deliberate</em> denormalization. Fan-out and chasm traps, surrogate vs natural keys, and where the OLTP/analytics trade-off actually bites.</p><h2 id="pareto-focus" tabindex="-1">Pareto focus <a class="header-anchor" href="#pareto-focus" aria-label="Permalink to &quot;Pareto focus&quot;">​</a></h2><p>If you only internalize these, you get most of the value:</p><ul><li><strong>Architecture is a workload decision, not a brand decision</strong> — ACID-heavy BI on curated data favors warehouses/lakehouses; raw-data-at-scale plus ML favors lakehouse; org-scale favors mesh <em>as an operating model</em>, not a product.</li><li><strong>Columnar + statistics = the whole trick</strong> — Parquet/ORC are fast because queries read fewer bytes and skip row groups via min/max metadata. Predicate pushdown is not an optimization, it is the design.</li><li><strong>Table formats are the real lakehouse</strong> — Iceberg/Delta/Hudi add ACID, time travel, and partition evolution to object storage. Choosing one matters more than the file format underneath.</li><li><strong>Declare the grain before anything else</strong> — in dimensional modeling, the fact table&#39;s row definition decides every join, every metric, every bug you will or will not have.</li><li><strong>Normalize until it hurts, then denormalize for reads</strong> — OLTP wants BCNF; analytics wants star schemas. The failure mode is running BI queries on a normalized schema, not the other way round.</li><li><strong>Surrogate keys are load-bearing</strong> — they are what make SCD Type 2 history possible. Never expose natural keys in fact tables.</li><li><strong>Every denormalization is a write-path contract</strong> — you are trading a join for the obligation to keep copies consistent. Fan-out traps punish people who forget which side of the join multiplies.</li></ul><p>Start with <a href="/Data-Knowledge/fundamentals/storage-architectures.html">Storage Architectures</a> — everything else sits on top of it.</p>',15))])}const D=n(u,[["render",f]]);export{v as __pageData,D as default};
